  1	/**
  2	 * Real-kernel verification of the cgroup resource limits on evaluator commands (v1.1.4 WP-1105 / audit A9).
  3	 *
  4	 * Every check launches a command through the production evaluator-command runner (`createContainedRunner`, the code
  5	 * behind `runArgv` that build and typecheck_clean use) with `resources` set small, and reads the kernel's own
  6	 * counters. Nothing here is an injected runner: the only injected seam is a pass-through spy that keeps the
  7	 * supervisor's report, which the runner otherwise reduces to status/signal/error.
  8	 *
  9	 * Skipped, with the reason printed, unless this host can run the contract for real: cgroup v2 with a systemd user
 10	 * manager that delegates cpu+memory+pids, Bubblewrap, prlimit, and a dedicated tmpfs in
 11	 * NEXUS_EVAL_TEST_WORKSPACE_ROOT (the same fixture `make test-ci` and CI provide). A skip is not verification.
 12	 *
 13	 * Safety: the supervisor applies and reads back memory.max, pids.max and cpu.max on the payload cgroup BEFORE the
 14	 * command starts, and refuses (never runs the command) when it cannot. The hog, the fork bomb and the busy loops only
 15	 * ever run inside that cgroup, with a wall-clock timeout.
 16	 */
 17	import { test } from "node:test";
 18	import type { TestContext } from "node:test";
 19	import assert from "node:assert/strict";
 20	import fs from "node:fs";
 21	import os from "node:os";
 22	import path from "node:path";
 23	import { randomUUID } from "node:crypto";
 24	import { spawnSync } from "node:child_process";
 25	import { fileURLToPath } from "node:url";
 26	
 27	const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
 28	const MIB = 1024 * 1024;
 29	const uid = process.getuid!();
 30	const USER_SERVICE = `/sys/fs/cgroup/user.slice/user-${uid}.slice/user@${uid}.service`;
 31	const APP_SLICE = path.join(USER_SERVICE, "app.slice");
 32	
 33	type Final = Record<string, any>;
 34	type Run = { result: any; final: Final | undefined; sampled: Sampled; marker: string; ms: number };
 35	type Sampled = { scopes: string[]; raw: Record<string, string> };
 36	
 37	const read = (file: string) => { try { return fs.readFileSync(file, "utf8"); } catch { return null; } };
 38	const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));
 39	
 40	/** Why this host cannot verify the contract for real, or null. Computed once; the probe is a harmless `true` in a scope. */
 41	let gate: Promise<{ reason: string | null; resources?: any }> | undefined;
 42	function hostGate() {
 43	  gate ??= (async () => {
 44	    if (process.platform !== "linux") return { reason: "not Linux" };
 45	    if (!fs.existsSync("/sys/fs/cgroup/cgroup.controllers")) return { reason: "no cgroup v2 unified hierarchy at /sys/fs/cgroup" };
 46	    if (!fs.existsSync(path.join(USER_SERVICE, "cgroup.kill"))) return { reason: "this kernel has no cgroup.kill (before 5.14): the harness could not stop a fork bomb" };
 47	    const delegated = read(path.join(USER_SERVICE, "cgroup.controllers"))?.trim().split(/\s+/) ?? [];
 48	    for (const controller of ["cpu", "memory", "pids"]) {
 49	      if (!delegated.includes(controller)) return { reason: `the systemd user manager does not delegate the ${controller} controller (${USER_SERVICE}/cgroup.controllers: "${delegated.join(" ")}")` };
 50	    }
 51	    if (!fs.existsSync(APP_SLICE)) return { reason: `${APP_SLICE} does not exist: transient scopes land elsewhere on this host, so the harness cannot watch them` };
 52	    if (!fs.existsSync("/usr/bin/pgrep")) return { reason: "pgrep is unavailable" };
 53	    if (!process.env.XDG_RUNTIME_DIR) return { reason: "XDG_RUNTIME_DIR is unset: no systemd user manager session" };
 54	    const workspaceRoot = process.env.NEXUS_EVAL_TEST_WORKSPACE_ROOT;
 55	    if (!workspaceRoot) return { reason: "NEXUS_EVAL_TEST_WORKSPACE_ROOT is unset: no dedicated capped tmpfs for the resource contract (run `make test-ci`)" };
 56	    const { resourceProbeProblem } = await import(path.join(ROOT, "eval/resources.mjs"));
 57	    const { sandboxAvailable } = await import(path.join(ROOT, "eval/isolate.mjs"));
 58	    if (!sandboxAvailable()) return { reason: "Bubblewrap is unavailable or cannot start here" };
 59	    if (!fs.existsSync("/usr/bin/prlimit")) return { reason: "prlimit is unavailable" };
 60	    const tmpfs = fs.statfsSync(workspaceRoot);
 61	    const resources = { cpuPercent: 50, memoryBytes: 64 * MIB, tasks: 16, storageBytes: tmpfs.blocks * tmpfs.bsize, workspaceRoot };
 62	    const problem = resourceProbeProblem(resources);
 63	    if (problem) return { reason: `the resource contract probe fails on this host: ${problem}` };
 64	    return { reason: null, resources };
 65	  })();
 66	  return gate;
 67	}
 68	
 69	/** The resources to use. Without the fixtures: skip with the reason and return null. With them set (CI, `make test-ci`): fail, as eval_integrity does, so a lost delegation cannot turn this file green by skipping. */
 70	async function requireHost(t: TestContext) {
 71	  const { reason, resources } = await hostGate();
 72	  if (reason && process.env.NEXUS_EVAL_TEST_WORKSPACE_ROOT) assert.fail(`the CI evaluator fixtures are configured (NEXUS_EVAL_TEST_WORKSPACE_ROOT is set) but the cgroup contract cannot run: ${reason}`);
 73	  if (reason) { t.skip(`cannot verify cgroup limits on this host: ${reason}`); return null; }
 74	  return resources;
 75	}
 76	
 77	/** Scope cgroups (under the user manager) whose payload leaf holds a process whose command line contains `marker`. */
 78	function scopesHolding(marker: string) {
 79	  const found: string[] = [];
 80	  let entries: string[] = [];
 81	  try { entries = fs.readdirSync(APP_SLICE); } catch { return found; }
 82	  for (const entry of entries) {
 83	    if (!entry.startsWith("run-") || !entry.endsWith(".scope")) continue;
 84	    const procs = read(path.join(APP_SLICE, entry, "payload", "cgroup.procs"));
 85	    if (!procs) continue;
 86	    for (const pid of procs.split("\n").filter(Boolean)) {
 87	      if ((read(`/proc/${pid}/cmdline`) ?? "").includes(marker)) { found.push(path.join(APP_SLICE, entry)); break; }
 88	    }
 89	  }
 90	  return found;
 91	}
 92	
 93	/** Poll the cgroup files of this run's scope while it lives, as raw evidence next to the supervisor's report (informational: a short run can end between ticks). */
 94	function startSampler(marker: string): { stop: () => Sampled } {
 95	  const scopes = new Set<string>();
 96	  const raw: Record<string, string> = {};
 97	  const timer = setInterval(() => {
 98	    for (const scope of scopesHolding(marker)) {
 99	      scopes.add(scope);
100	      for (const file of ["memory.events", "pids.events", "cpu.stat", "memory.max", "pids.max", "cpu.max", "memory.swap.max", "memory.oom.group"]) {
101	        const text = read(path.join(scope, "payload", file));
102	        if (text !== null) raw[file] = text.trim();
103	      }
104	    }
105	  }, 15);
106	  return { stop: () => { clearInterval(timer); return { scopes: [...scopes], raw }; } };
107	}
108	
109	async function launch(resources: any, command: string, args: string[], timeoutMs: number, opts: { env?: Record<string, string | undefined>; cwd?: string } = {}): Promise<Run> {
110	  const { createContainedRunner } = await import(path.join(ROOT, "eval/evaluators/code/command.mjs"));
111	  const { runIsolatedProcess } = await import(path.join(ROOT, "eval/isolate.mjs"));
112	  let final: Final | undefined;
113	  const runner = createContainedRunner({
114	    runIsolatedProcess: async (spec: any, options: any) => { const outcome = await runIsolatedProcess(spec, options); final = outcome.resources; return outcome; },
115	  });
116	  const marker = `nexus-a9-${randomUUID()}`;
117	  const cwd = opts.cwd ?? fs.mkdtempSync(path.join(resources.workspaceRoot, "a9-cgroup-"));
118	  const saved: Record<string, string | undefined> = {};
119	  for (const [key, value] of Object.entries(opts.env ?? {})) { saved[key] = process.env[key]; if (value === undefined) delete process.env[key]; else process.env[key] = value; }
120	  const sampler = startSampler(marker);
121	  const started = Date.now();
122	  try {
123	    const result = await runner(command, [...args, marker], { cwd, timeoutMs, resources });
124	    const ms = Date.now() - started;
125	    return { result, final, sampled: sampler.stop(), marker, ms };
126	  } finally {
127	    sampler.stop();
128	    for (const [key, value] of Object.entries(saved)) { if (value === undefined) delete process.env[key]; else process.env[key] = value; }
129	    if (!opts.cwd) fs.rmSync(cwd, { recursive: true, force: true });
130	  }
131	}
132	
133	/** The shell script runs as `sh -c <script> <marker>`: `$0` carries the marker into every process's argv. */
134	const sh = (resources: any, script: string, timeoutMs: number, opts = {}) => launch(resources, "/bin/sh", ["-c", script], timeoutMs, opts);
135	
136	/** The run's scope and everything in it is gone: no scope directory, no process carrying the marker. */
137	async function assertCleanedUp(run: Run) {
138	  assert.ok(run.sampled.scopes.length >= 1, "the sampler never saw this run's scope, so cleanup would be vacuous");
139	  const deadline = Date.now() + 8000;
140	  let leftover: string[] = run.sampled.scopes.filter((scope) => fs.existsSync(scope));
141	  while (leftover.length && Date.now() < deadline) { await sleep(100); leftover = run.sampled.scopes.filter((scope) => fs.existsSync(scope)); }
142	  if (leftover.length) for (const scope of leftover) { try { fs.writeFileSync(path.join(scope, "cgroup.kill"), "1"); } catch {} }
143	  assert.deepEqual(leftover, [], "a transient scope cgroup outlived its command");
144	  const pgrep = spawnSync("/usr/bin/pgrep", ["-f", run.marker], { encoding: "utf8" });
145	  assert.equal(pgrep.status, 1, `a process carrying the run marker survived: ${pgrep.stdout}`);
146	  assert.equal(run.final?.cleaned, true, JSON.stringify(run.final));
147	}
148	
149	function reportOf(run: Run): Final {
150	  assert.ok(run.final, `the resource supervisor produced no final report: ${JSON.stringify(run.result)}`);
151	  return run.final;
152	}
153	
154	function note(t: TestContext, label: string, run: Run) {
155	  t.diagnostic(`${label} ms=${run.ms} result=${JSON.stringify({ ...run.result, stdout: run.result.stdout.slice(0, 200), stderr: run.result.stderr.slice(0, 300) })}`);
156	  t.diagnostic(`${label} supervisor-report=${JSON.stringify(run.final)}`);
157	  for (const [file, text] of Object.entries(run.sampled.raw)) t.diagnostic(`${label} raw ${file}=${JSON.stringify(text)}`);
158	}
159	
160	test("the host fixtures for the cgroup limit checks are reported (a skip below is not verification)", async (t) => {
161	  const { reason } = await hostGate();
162	  t.diagnostic(reason ? `SKIPPED: ${reason}` : `kernel ${os.release()} cgroup2 user delegation present; checks run for real`);
163	});
164	
165	test("a memory hog is OOM-killed inside its cgroup, reported as a memory-limit kill, and never exceeds its limit", { timeout: 60_000 }, async (t) => {
166	  const resources = await requireHost(t);
167	  if (!resources) return;
168	  // `tail` of an endless line without a newline buffers all of it: unbounded anonymous memory.
169	  const run = await launch(resources, "/usr/bin/tail", ["/dev/zero"], 30_000);
170	  note(t, "memory", run);
171	  const final = reportOf(run);
172	  assert.equal(final.limits["memory.max"], String(resources.memoryBytes), "the 64 MiB limit was read back from the kernel before the command ran");
173	  assert.equal(final.limits["memory.swap.max"], "0");
174	  assert.ok(final.oomKills >= 1, `memory.events oom_kill: ${JSON.stringify(final)}`);
175	  assert.ok(final.memoryMaxEvents >= 1);
176	  assert.equal(typeof final.memoryPeakBytes, "number", "memory.peak was not reported");
177	  assert.ok(final.memoryPeakBytes <= resources.memoryBytes, `peak ${final.memoryPeakBytes} exceeded the limit`);
178	  assert.notEqual(run.result.status, 0);
179	  assert.equal(run.result.timedOut, false, "it died of the limit, not the wall clock");
180	  assert.match(run.result.error ?? "", /memory limit/, "the operator is told a limit was hit");
181	  await assertCleanedUp(run);
182	});
