184	test("a shell that forks past pids.max gets EAGAIN and the supervisor records it", { timeout: 60_000 }, async (t) => {
185	  const resources = await requireHost(t);
186	  if (!resources) return;
187	  const run = await sh(resources, "for i in $(seq 40); do sleep 3 & done; wait", 20_000);
188	  note(t, "pids-loop", run);
189	  const final = reportOf(run);
190	  assert.equal(final.limits["pids.max"], String(resources.tasks));
191	  assert.ok(final.pidsMaxEvents >= 1, `pids.events max: ${JSON.stringify(final)}`);
192	  assert.equal(typeof final.pidsPeak, "number", "pids.peak was not reported");
193	  assert.ok(final.pidsPeak <= resources.tasks, `pids.peak ${final.pidsPeak} > ${resources.tasks}`);
194	  assert.match(run.result.stderr, /Cannot fork|Resource temporarily unavailable|EAGAIN/i, "the shell's own fork failed with EAGAIN");
195	  await assertCleanedUp(run);
196	});
197	
198	test("a real fork bomb is bounded by pids.max and killed with its cgroup; fork keeps working outside it", { timeout: 60_000 }, async (t) => {
199	  const resources = await requireHost(t);
200	  if (!resources) return;
201	  // The classic bomb in a respawn loop, silenced (its error spam would hit the output cap), stopped by the wall clock, never outside the cgroup.
202	  // bash survives a failed fork (dash exits on the first one), so the loop keeps bombing until the clock stops it.
203	  const bomb = "b() { b | b & }; while :; do b 2>/dev/null; done";
204	  const during: number[] = [];
205	  const probe = setInterval(() => { during.push(spawnSync("/usr/bin/true").status ?? -1); }, 250);
206	  let run: Run;
207	  try { run = await launch(resources, "/usr/bin/bash", ["-c", bomb], 4000); } finally { clearInterval(probe); }
208	  note(t, "fork-bomb", run);
209	  const final = reportOf(run);
210	  assert.equal(run.result.timedOut, true);
211	  assert.ok(final.pidsMaxEvents >= 5, `pids.events max=${final.pidsMaxEvents}`);
212	  assert.equal(typeof final.pidsPeak, "number", "pids.peak was not reported");
213	  assert.ok(final.pidsPeak <= resources.tasks, `pids.peak ${final.pidsPeak} > ${resources.tasks}`);
214	  const forked = during.filter((status) => status === 0).length;
215	  assert.ok(during.length >= 3 && forked >= Math.ceil(during.length * 0.8), `the host could not fork while the bomb ran: ${JSON.stringify(during)}`);
216	  await assertCleanedUp(run);
217	});
218	
219	for (const [cpuPercent, loops] of [[20, 2], [50, 3]] as const) {
220	  test(`a CPU burner is throttled to cpu.max at ${cpuPercent}% (${loops} busy loops for 2 s)`, { timeout: 60_000 }, async (t) => {
221	    const base = await requireHost(t);
222	    if (!base) return;
223	    const resources = { ...base, cpuPercent };
224	    const busy = Array.from({ length: loops }, () => "timeout 2 sh -c 'while :; do :; done' &").join(" ");
225	    const run = await sh(resources, `${busy} wait`, 20_000);
226	    note(t, `cpu-${cpuPercent}`, run);
227	    const final = reportOf(run);
228	    const quotaUsec = (cpuPercent / 100) * 2_000_000;
229	    t.diagnostic(`cpu-${cpuPercent} usage_usec=${final.cpuUsageUsec} throttled_usec=${final.cpuThrottledUsec} quota_over_2s_usec=${quotaUsec} unthrottled_demand_usec=${loops * 2_000_000}`);
230	    assert.equal(final.limits["cpu.max"], `${cpuPercent * 1000} 100000`);
231	    assert.ok(final.cpuThrottledUsec > 0, "cpu.stat throttled_usec must be > 0");
232	    // Demand is `loops` full cores; the quota is a fraction of one. Allow a one-period burst and scheduler slack above,
233	    // 
234	    assert.ok(final.cpuUsageUsec <= quotaUsec * 1.5, `used ${final.cpuUsageUsec} us, quota allows ~${quotaUsec}`);
235	    assert.ok(final.cpuUsageUsec > 0, `used only ${final.cpuUsageUsec} us, expected near ${quotaUsec}`);
236	    assert.equal(run.result.error, null);
237	    await assertCleanedUp(run);
238	  });
239	}
