241	test("a clean command under the same limits succeeds untouched (the limits do not break ordinary work)", { timeout: 60_000 }, async (t) => {
242	  const resources = await requireHost(t);
243	  if (!resources) return;
244	  const cwd = fs.mkdtempSync(path.join(resources.workspaceRoot, "a9-cgroup-"));
245	  let run: Run;
246	  try {
247	    run = await sh(resources, "touch /workspace/ran; echo ok; sleep 0.3", 20_000, { cwd });
248	    // The witness the fail-closed tests rely on can fire when the command does run contained.
249	    assert.equal(fs.existsSync(path.join(cwd, "ran")), true);
250	  } finally { fs.rmSync(cwd, { recursive: true, force: true }); }
251	  note(t, "control", run);
252	  assert.equal(run.result.status, 0);
253	  assert.equal(run.result.error, null);
254	  assert.equal(run.final?.oomKills, 0);
255	  assert.equal(run.final?.pidsMaxEvents, 0);
256	  await assertCleanedUp(run);
257	});
