259	test("without a usable systemd user manager a configured contract refuses to run the command (fails closed)", { timeout: 60_000 }, async (t) => {
260	  const resources = await requireHost(t);
261	  if (!resources) return;
262	  for (const [label, env] of [
263	    ["XDG_RUNTIME_DIR unset", { XDG_RUNTIME_DIR: undefined, DBUS_SESSION_BUS_ADDRESS: undefined }],
264	    ["XDG_RUNTIME_DIR points at no user manager", { XDG_RUNTIME_DIR: path.join(os.tmpdir(), `no-user-manager-${randomUUID()}`), DBUS_SESSION_BUS_ADDRESS: undefined }],
265	  ] as const) {
266	    const cwd = fs.mkdtempSync(path.join(resources.workspaceRoot, "a9-cgroup-"));
267	    try {
268	      const run = await sh(resources, "touch /workspace/ran; echo ran", 15_000, { env, cwd });
269	      t.diagnostic(`fail-closed[${label}] result=${JSON.stringify(run.result)} report=${JSON.stringify(run.final)}`);
270	      assert.notEqual(run.result.error, null, `${label}: the operator must get a diagnostic`);
271	      assert.notEqual(run.result.status, 0, `${label}: must not look like a success`);
272	      assert.doesNotMatch(run.result.stdout, /ran/, `${label}: the command ran without limits`);
273	      assert.equal(fs.existsSync(path.join(cwd, "ran")), false, `${label}: the command ran without limits`);
274	    } finally { fs.rmSync(cwd, { recursive: true, force: true }); }
275	  }
276	});
277	
278	test("when the cgroup parent is not writable the supervisor refuses before the command starts (fails closed)", { timeout: 60_000 }, async (t) => {
279	  const resources = await requireHost(t);
280	  if (!resources) return;
281	  // Run the same production runner in a child whose /sys/fs/cgroup is a read-only bind: the supervisor, started in
282	  // this mount namespace by systemd-run, cannot create its leaves, which is what a host without delegation looks like.
283	  const cwd = fs.mkdtempSync(path.join(resources.workspaceRoot, "a9-cgroup-"));
284	  const script = `
285	    import { createContainedRunner } from ${JSON.stringify(path.join(ROOT, "eval/evaluators/code/command.mjs"))};
286	    const run = createContainedRunner();
287	    const cwd = ${JSON.stringify(cwd)};
288	    const result = await run("/bin/sh", ["-c", "touch /workspace/ran; echo ran"], { cwd, timeoutMs: 15000, resources: ${JSON.stringify(resources)} });
289	    console.log(JSON.stringify(result));`;
290	  try {
291	    const child = spawnSync("/usr/bin/bwrap", [
292	      "--bind", "/", "/", "--dev-bind", "/dev", "/dev", "--ro-bind", "/sys/fs/cgroup", "/sys/fs/cgroup",
293	      "--die-with-parent", "--", process.execPath, "--input-type=module", "-e", script,
294	    ], { encoding: "utf8", timeout: 40_000, env: { PATH: "/usr/bin:/bin", XDG_RUNTIME_DIR: process.env.XDG_RUNTIME_DIR, DBUS_SESSION_BUS_ADDRESS: process.env.DBUS_SESSION_BUS_ADDRESS ?? "" } });
295	    t.diagnostic(`readonly-cgroup bwrap status=${child.status} stdout=${child.stdout.trim().slice(-600)} stderr=${child.stderr.trim().slice(-300)}`);
296	    if (child.status !== 0) { t.skip(`cannot simulate an unwritable cgroup parent here (outer bwrap failed: ${child.stderr.trim().slice(-200)})`); return; }
297	    const result = JSON.parse(child.stdout.trim().split("\n").pop()!);
298	    assert.match(result.error ?? "", /could not apply resource limits: EROFS/, JSON.stringify(result));
299	    assert.doesNotMatch(result.stdout, /ran/);
300	    assert.notEqual(result.status, 0);
301	    assert.equal(fs.existsSync(path.join(cwd, "ran")), false, "the command ran without its limits");
302	  } finally { fs.rmSync(cwd, { recursive: true, force: true }); }
303	});

